DO $runtime_graph_sessions$ BEGIN
CREATE TABLE platform_runtime_graph_sessions(id UUID PRIMARY KEY,tenant_id VARCHAR(36) NOT NULL,owner_id VARCHAR(36) NOT NULL,agent_run_id VARCHAR(36) NOT NULL UNIQUE,bundle_hash VARCHAR(71) NOT NULL,cursor_sequence BIGINT NOT NULL,completed_command_ids JSONB NOT NULL,pending_command_id VARCHAR(200),pending_input_hash VARCHAR(71),state VARCHAR(32) NOT NULL,revision BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT ck_runtime_graph_session CHECK(bundle_hash ~ '^sha256:[0-9a-f]{64}$' AND cursor_sequence>=0 AND revision>0 AND state IN('ACTIVE','WAITING_FOR_COMMAND','BLOCKED','COMPLETED') AND ((state='WAITING_FOR_COMMAND')=(pending_command_id IS NOT NULL AND pending_input_hash IS NOT NULL))));
CREATE TABLE platform_runtime_graph_commands(graph_session_id UUID NOT NULL,command_id VARCHAR(200) NOT NULL,input_hash VARCHAR(71) NOT NULL,state VARCHAR(16) NOT NULL,revision BIGINT NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(graph_session_id,command_id),CONSTRAINT fk_runtime_graph_command_session FOREIGN KEY(graph_session_id) REFERENCES platform_runtime_graph_sessions(id) ON DELETE CASCADE,CONSTRAINT ck_runtime_graph_command CHECK(input_hash ~ '^sha256:[0-9a-f]{64}$' AND state IN('PENDING','CONFIRMED','BLOCKED') AND revision>0));
CREATE INDEX idx_runtime_graph_session_scope ON platform_runtime_graph_sessions(tenant_id,owner_id,updated_at DESC); END $runtime_graph_sessions$;
